+impl<'s> Drop for Worker<'s> {
+    fn drop(&mut self) {
+        // If this worker is being dropped because the caller's visitor
+        // panicked, then it will never deactivate itself and so the other
+        // workers could never conclude that all work has been exhausted.
+        // Tell them to quit so that the traversal terminates and the panic
+        // can be propagated to the caller.
+        if std::thread::panicking() {
+            self.quit_now();
+        }
+    }
+}
